export default function next({ previous, response, userId, username }) {
  if (!/^\d+$/.test(userId) || !username.trim()) throw Error("Configure Threads ID and username");
  let s = previous ?? { phase: "posts", after: null, posts: [], index: 0 };
  const url = (path, fields, after) =>
    "https://graph.threads.net/v1.0/" +
    path +
    "?" +
    new URLSearchParams({ fields, limit: "100", ...(after ? { after } : {}) });
  const page = (r) => {
    if (!r || !Array.isArray(r.data)) throw Error("Invalid Threads page");
    const after = r.paging?.next ? r.paging?.cursors?.after : null;
    if (r.paging?.next && !after) throw Error("Missing Threads cursor");
    return after;
  };
  if (s.wait === "posts") {
    s.posts.push(...response.data);
    s.after = page(response);
    s.wait = null;
    if (!s.after) s.phase = "next";
  } else if (s.wait === "root") {
    if (!response || String(response.id) !== String(s.current.id))
      throw Error("Mismatched Threads root");
    s.root = response;
    s.replies = [];
    s.after = null;
    s.phase = "replies";
    s.wait = null;
  } else if (s.wait === "replies") {
    s.after = page(response);
    s.replies.push(...response.data.filter((x) => x.username === username));
    s.wait = null;
    if (!s.after) s.phase = "ready";
  }
  if (s.phase === "posts") {
    s.wait = "posts";
    return {
      state: s,
      step: "http",
      url:
        url(userId + "/threads", "id,media_type,permalink,timestamp", s.after) +
        "&since=" +
        encodeURIComponent(
          s.since ?? (s.since = new Date(Date.now() - 86400000).toISOString().slice(0, 10)),
        ),
      post: {},
    };
  }
  if (s.phase === "next") {
    if (s.index >= s.posts.length)
      return { state: s, step: "done", url: "https://graph.threads.net/", post: {} };
    s.current = s.posts[s.index++];
    if (!/^\d+$/.test(String(s.current.id))) throw Error("Invalid post ID");
    s.wait = "root";
    return {
      state: s,
      step: "http",
      url: url(
        s.current.id,
        "id,media_type,media_url,children{media_url},permalink,username,text,timestamp",
        null,
      ),
      post: {},
    };
  }
  if (s.phase === "replies") {
    s.wait = "replies";
    return {
      state: s,
      step: "http",
      url:
        url(
          s.current.id + "/conversation",
          "id,text,username,timestamp,media_type,media_url,children{media_url}",
          s.after,
        ) + "&reverse=false",
      post: {},
    };
  }
  if (s.phase === "ready") {
    const p = { ...s.root, replies: s.replies };
    s.phase = "next";
    return { state: s, step: "post", url: "https://graph.threads.net/", post: p };
  }
  throw Error("Invalid state");
}

