export default async function plan({ post, sourceId, existing, acknowledge, resolution }, ctx) {
  const id = String(post.id ?? "");
  if (!/^\d+$/.test(id) || !post.permalink || !post.timestamp) throw Error("Invalid post identity");
  existing = existing?.results;
  if (!Array.isArray(existing)) throw Error("Invalid Notion query");
  if (existing.length > 1) throw Error("Multiple Notion pages match post");
  const key = "threads-archive:" + id;
  let status = await ctx.state.get(key);
  if (status?.phase === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      if (existing.length !== 1) throw Error("Confirmed page must be visible in Notion");
      await ctx.state.set(key, { phase: "done" });
      return { write: false, key, parent: {}, properties: {}, children: [] };
    }
    if (existing.length) throw Error("A page already exists");
    await ctx.state.set(key, null);
    status = null;
  }
  if (existing.length || status?.phase === "done")
    return { write: false, key, parent: {}, properties: {}, children: [] };
  const children = [];
  for (const p of [post, ...(post.replies ?? [])]) {
    if (p.text) {
      for (let i = 0; i < p.text.length; i += 1900)
        children.push({
          object: "block",
          type: "paragraph",
          paragraph: {
            rich_text: [{ type: "text", text: { content: p.text.slice(i, i + 1900) } }],
          },
        });
    }
    const urls =
      p.children?.data?.map((x) => x.media_url).filter(Boolean) ??
      (p.media_url ? [p.media_url] : []);
    for (const u of urls) {
      if (!/^https:\/\//.test(u)) throw Error("Invalid media URL");
      children.push({ object: "block", type: "embed", embed: { url: u } });
    }
  }
  if (children.length > 100) throw Error("Post exceeds one Notion page request");
  const properties = {
    Name: { title: [{ text: { content: post.permalink } }] },
    "Threads ID": { rich_text: [{ text: { content: id } }] },
    "Post Date": { date: { start: post.timestamp } },
    Source: { multi_select: [{ name: "Threads" }] },
    "Import Check": { checkbox: false },
    Username: { rich_text: [{ text: { content: post.username ?? "" } }] },
  };
  await ctx.state.set(key, { phase: "pending" });
  return {
    write: true,
    key,
    parent: { type: "data_source_id", data_source_id: sourceId },
    properties,
    children,
  };
}

